"""Decode the stock mode-register table; never changes firmware or camera state."""
from pathlib import Path
import hashlib
import json
import struct
from capstone import Cs, CS_ARCH_ARM, CS_MODE_ARM

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'analysis/firmware'
b = (OUT / 'MAIN_c0000000.bin').read_bytes()
assert hashlib.sha256(b).hexdigest() == 'aaa5208a028d9c4aebb9cc8614add723d456e96b2a95914f433079954320e622'
base, count = struct.unpack_from('<2I', b, 0xb5fda4)
assert (base, count) == (0xc0b5fdac, 70)
md = Cs(CS_ARCH_ARM, CS_MODE_ARM)
mapping = []
for word_index in range(1, 162):
    address = 0xc03258f8 + (word_index - 1) * 32
    code = b[address - 0xc0000000:address - 0xc0000000 + 32]
    ins = list(md.disasm(code, address))
    assert len(ins) == 8
    # These five instructions calculate descriptor->table + index*648.
    assert code[:20].hex() == '001094e5050285e0001091e5050380e0800181e0'
    assert ins[5].mnemonic == 'ldr'
    assert ins[5].op_str == f'r1, [r0, #{hex(word_index*4) if word_index*4 >= 10 else word_index*4}]'
    assert ins[6].mnemonic in ('mov', 'movw') and ins[6].op_str.startswith('r0, #')
    assert (ins[7].mnemonic, ins[7].op_str) == ('bl', '#0xc0322c70')
    mapping.append(dict(word_index=word_index, row_offset=word_index*4,
                        register=int(ins[6].op_str.split('#')[1], 0), call_address=ins[7].address))
assert len({x['register'] for x in mapping}) == 161
geometry = json.loads((OUT / 'sensor-modes.json').read_text())
rows = []
for i in range(count):
    address = base + i * 648
    words = struct.unpack_from('<162I', b, address - 0xc0000000)
    assert words[0] == geometry[i]['mode_id']
    rows.append(dict(index=i, mode_id=words[0], address=address, words=list(words)))
data = dict(descriptor=0xc0b5fda4, table=base, stride=648, count=count,
            scope='161 table-fed writes only; later dynamic writes and other mode setup routines excluded',
            mapping=mapping, rows=rows)
(OUT / 'sensor-registers.json').write_text(json.dumps(data, indent=2)+'\n')
by_id = {r['mode_id']: r for r in rows}
lines = ['# Stock sensor register comparison', '',
         'Generated by tools/extract_sensor_registers.py from hash-pinned MAIN. All 161 table-fed write blocks validated against ARM instructions; all 70 mode IDs cross-checked against the independent geometry table. This is a comparison of programmed values, not a sensor datasheet or a patch.', '',
         'Later dynamic writes to 0xCE and 0xD1–0xD3, receiver configuration, timing updates, and processing/buffer setup are outside this table comparison.', '']
for target in (3, 121, 98, 11, 218):
    changes = [m for m in mapping if by_id[151]['words'][m['word_index']] != by_id[target]['words'][m['word_index']]]
    lines += [f'## Mode 151 versus {target}: {len(changes)} differing table-fed registers', '', '| Register | Row offset | Mode 151 | Mode '+str(target)+' |', '|---|---|---:|---:|']
    for m in changes:
        j = m['word_index']
        lines.append(f"| 0x{m['register']:04X} | 0x{m['row_offset']:03X} | {by_id[151]['words'][j]} | {by_id[target]['words'][j]} |")
    lines += ['']
(OUT / 'sensor-register-comparison.md').write_text('\n'.join(lines)+'\n')
print('Validated 70 rows × 161 table-fed register writes.')
print('\n'.join(lines[:35]))
